python3 - <<'E'
p='src/CheckoutPricing.Application/CalculatePayableTotal.cs'
s=open(p).read()
s=s.replace('''    public int For(LoyaltyTier tier, int subtotalCents)
    {
        return subtotalCents;
    }''','''    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var baseRate = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9
        };
        var bonus = subtotalCents switch
        {
            >= 20000 => 3,
            >= 5000 => 1,
            _ => 0
        };
        var rate = Math.Min(baseRate + bonus, 10);
        return subtotalCents - subtotalCents * rate / 100;
    }''')
open(p,'w').write(s)
E
